import{_ as s,o as a,c as n,a2 as p}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"产品静物 / 电商主图","description":"","frontmatter":{},"headers":[],"relativePath":"prompts/product-still.md","filePath":"prompts/product-still.md","lastUpdated":1785729506000}'),l={name:"prompts/product-still.md"};function o(r,t,e,d,i,c){return a(),n("div",null,[...t[0]||(t[0]=[p(`<h1 id="产品静物-电商主图" tabindex="-1">产品静物 / 电商主图 <a class="header-anchor" href="#产品静物-电商主图" aria-label="Permalink to &quot;产品静物 / 电商主图&quot;">​</a></h1><p>四条经过结构化整理的 Prompt，覆盖静态视觉最常见的需求。方括号 <code>[]</code> 处替换成你的内容。</p><hr><h2 id="_01-·-电商白底主图" tabindex="-1">01 · 电商白底主图 <a class="header-anchor" href="#_01-·-电商白底主图" aria-label="Permalink to &quot;01 · 电商白底主图&quot;">​</a></h2><p><strong>适用场景</strong> 平台主图、详情页首图。要求干净、无干扰、产品居中、留白充足。 <strong>不适用</strong>：需要氛围和情绪的品牌广告——白底图是功能性的，不负责传达调性。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[产品，例如：一支银色金属保温杯] 置于纯白背景中央，</span></span>
<span class="line"><span>电商产品摄影，商业级白底图，</span></span>
<span class="line"><span>微距镜头，全景深，正面平视机位，产品完整入画且四周留白充足，</span></span>
<span class="line"><span>均匀柔和的三点布光，无强烈阴影，仅在底部有一道极淡的接触阴影，</span></span>
<span class="line"><span>方图 1:1，超高细节，产品边缘锐利</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、logo、背景杂物、强反光、变形</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>在控制什么</th><th>想改效果时</th></tr></thead><tbody><tr><td>全景深</td><td>产品从前到后都清晰</td><td>电商主图必须这样，不要虚化</td></tr><tr><td>均匀柔和的三点布光</td><td>消除硬阴影</td><td>想要更有质感改成 <code>侧逆光</code></td></tr><tr><td>极淡的接触阴影</td><td>防止产品&quot;浮空&quot;</td><td>完全去掉会显假</td></tr><tr><td>四周留白充足</td><td>符合平台裁切要求</td><td>平台规则不同，自行调整</td></tr></tbody></table><p><strong>常见翻车点</strong></p><ul><li><strong>产品细节被改写</strong>。生成模型不认识你的具体产品，它画的是&quot;一支保温杯&quot;而不是&quot;你的那支保温杯&quot;。**只要产品有 logo、有特定造型，就别指望纯生成。**务实做法：用 AI 生成背景与光环境，产品用实拍图合成。</li><li><strong>&quot;纯白&quot;不够白</strong>。生成的白底常带灰或渐变，平台审核可能不过。后期用色阶拉一下。</li><li><strong>反光处出现幻觉细节</strong>。金属和玻璃的反光区域是重灾区，会出现不存在的图案。放大检查。</li></ul><hr><h2 id="_02-·-氛围产品图-品牌调性向" tabindex="-1">02 · 氛围产品图（品牌调性向） <a class="header-anchor" href="#_02-·-氛围产品图-品牌调性向" aria-label="Permalink to &quot;02 · 氛围产品图（品牌调性向）&quot;">​</a></h2><p><strong>适用场景</strong> 品牌 KV、社媒配图、详情页的氛围段落。要传达调性，不要求产品绝对精确。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[产品] 放在 [材质表面，例如：深色胡桃木桌面] 上，</span></span>
<span class="line"><span>旁边有 [一到两个呼应元素，例如：一块正在融化的冰、几片散落的咖啡豆]，</span></span>
<span class="line"><span>[品类] 高端广告摄影，[色调，例如：暗调暖色]，轻微胶片颗粒，</span></span>
<span class="line"><span>微距镜头，浅景深 f/2.0，产品清晰而背景自然虚化，微俯机位，</span></span>
<span class="line"><span>侧逆光，一束柔和的硬光从右后方打来，产品边缘有明亮轮廓光，背景压暗，</span></span>
<span class="line"><span>竖版 4:5，高细节</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、杂乱背景、塑料感、过曝</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>在控制什么</th></tr></thead><tbody><tr><td>呼应元素</td><td>讲故事的关键。冰=冷饮，咖啡豆=原料，织物=温暖</td></tr><tr><td>轻微胶片颗粒</td><td>去掉&quot;AI 味&quot;最有效的一个词，数字感太干净反而假</td></tr><tr><td>浅景深 f/2.0</td><td>背景虚化，这是&quot;贵&quot;的主要来源</td></tr><tr><td>侧逆光 + 轮廓光</td><td>把产品从背景里分离出来</td></tr><tr><td>背景压暗</td><td>提高对比，突出主体</td></tr></tbody></table><p><strong>常见翻车点</strong></p><ul><li><strong>呼应元素喧宾夺主</strong>。写超过两个装饰元素，画面会变乱，产品被淹没。<strong>最多两个。</strong></li><li><strong>色调和品牌 VI 对不上</strong>。生成的色温是随机的。同一组图要统一色调，靠后期调色比反复重生成快得多。</li><li><strong>反光和阴影方向不一致</strong>。多个元素的光影方向对不上是 AI 图的典型破绽，放大检查。</li></ul><hr><h2 id="_03-·-场景使用图-产品在真实环境中" tabindex="-1">03 · 场景使用图（产品在真实环境中） <a class="header-anchor" href="#_03-·-场景使用图-产品在真实环境中" aria-label="Permalink to &quot;03 · 场景使用图（产品在真实环境中）&quot;">​</a></h2><p><strong>适用场景</strong> 展示产品的使用情境，让消费者代入。信息流广告、种草图常用。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[人物描述，例如：一个二十多岁的女性] 在 [具体场景，例如：清晨的小户型厨房] 里</span></span>
<span class="line"><span>[使用产品的动作，例如：双手捧着马克杯]，</span></span>
<span class="line"><span>生活方式摄影，纪实风格，自然不摆拍，[色调]，轻微胶片颗粒，</span></span>
<span class="line"><span>35mm 镜头，中景，浅景深，平视机位，</span></span>
<span class="line"><span>[光源，例如：从左侧窗户进来的柔和晨光]，人物面部有自然的明暗过渡，</span></span>
<span class="line"><span>竖版 9:16，高细节</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、变形的手、多余的手指、生硬的摆拍姿态、过度磨皮</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>在控制什么</th></tr></thead><tbody><tr><td>纪实风格，自然不摆拍</td><td>对抗&quot;广告模特假笑脸&quot;，这一句很关键</td></tr><tr><td>35mm</td><td>接近人眼视角，代入感最强</td></tr><tr><td>变形的手（负向）</td><td>AI 画手仍是高频问题，必须排除</td></tr><tr><td>过度磨皮（负向）</td><td>皮肤太完美会假，留一点质感更可信</td></tr></tbody></table><p><strong>常见翻车点</strong></p><ul><li><strong>手部</strong>。凡是手接触产品的画面，先检查手指数量和关节走向。这是最容易被发现的破绽。<strong>能用中景就别用近景拍手。</strong></li><li><strong>人物表情用力过猛</strong>。生成模型偏好夸张笑容，看起来像库存图。在 Prompt 里写 <code>平静的表情</code>、<code>不看镜头</code> 能缓解。</li><li><strong>产品在场景中比例失真</strong>。手拿的杯子有时会大得离谱。写明 <code>产品尺寸真实合理</code> 有一定帮助，但更可靠的是多生成几版挑一张。</li></ul><hr><h2 id="_04-·-概念视觉-超现实、创意向" tabindex="-1">04 · 概念视觉（超现实、创意向） <a class="header-anchor" href="#_04-·-概念视觉-超现实、创意向" aria-label="Permalink to &quot;04 · 概念视觉（超现实、创意向）&quot;">​</a></h2><p><strong>适用场景</strong> 需要一个记忆点强烈的画面。海报、开屏、社媒话题图。这类图正是 AI 相对传统拍摄优势最大的地方——因为实拍做不出来或成本极高。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[超现实概念，例如：一杯咖啡的表面延展成一片平静的湖面，湖上有一叶小舟]，</span></span>
<span class="line"><span>超现实主义广告视觉，概念摄影，[色调]，简洁构图，大量留白，</span></span>
<span class="line"><span>广角镜头，全景深，微仰机位，</span></span>
<span class="line"><span>[戏剧化光线，例如：单一光源从上方打下，形成强烈明暗对比]，</span></span>
<span class="line"><span>竖版 9:16，高细节，画面干净</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、杂乱、元素过多</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>在控制什么</th></tr></thead><tbody><tr><td>超现实概念</td><td>核心。必须是一个<strong>具体的视觉转化</strong>，不是抽象说法</td></tr><tr><td>简洁构图，大量留白</td><td>概念图最忌堆料，一个概念一张图</td></tr><tr><td>戏剧化光线</td><td>超现实画面需要强光影支撑，柔光会显得平</td></tr></tbody></table><p><strong>常见翻车点</strong></p><ul><li><strong>概念不够具体</strong>。「表达自由的感觉」出不了图，「一只鸟从打开的笼子里飞出，笼子由钥匙组成」能出图。<strong>概念必须能拆成物体和关系。</strong></li><li><strong>一张图塞两个概念</strong>。会互相打架，出来的东西两边都不像。一张图一个概念。</li><li><strong>落地性差</strong>。概念图很酷但和产品无关，客户会问&quot;这跟我的产品有什么关系&quot;。<strong>做之前先想清楚概念和卖点的连接点是什么。</strong></li></ul><hr><h2 id="通用检查清单" tabindex="-1">通用检查清单 <a class="header-anchor" href="#通用检查清单" aria-label="Permalink to &quot;通用检查清单&quot;">​</a></h2><p>出图后按这个顺序检查，能筛掉大部分废片：</p><ul><li>[ ] 产品外观是否准确（logo、比例、颜色）</li><li>[ ] 有没有手部 / 肢体畸形</li><li>[ ] 有没有生成出乱码文字（AI 生成的&quot;文字&quot;基本都是乱码，能去就去）</li><li>[ ] 光影方向是否一致</li><li>[ ] 反光和高光区有没有幻觉细节</li><li>[ ] 分辨率是否够投放要求</li><li>[ ] 有没有和竞品雷同的视觉元素</li></ul><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>结构原理 → <a href="/prompts/structure">Prompt 结构通法</a></li><li>批量生产的实际流程 → <a href="/cases/case-02-ecommerce-visual">案例 02 · 电商主图批量生产</a></li></ul>`,44)])])}const u=s(l,[["render",o]]);export{g as __pageData,u as default};
